import{_ as e,o as t,c as o,a2 as d}from"./chunks/framework.DWpAL8O0.js";const p=JSON.parse('{"title":"Overview","description":"","frontmatter":{"title":"Overview","kind":"page"},"headers":[],"relativePath":"api/overview.md","filePath":"api/overview.md"}'),i={name:"api/overview.md"};function r(c,a,s,m,g,n){return t(),o("div",null,[...a[0]||(a[0]=[d('<h1 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview {#overview}&quot;">​</a></h1><p>The whole public API hangs off a single object of class <a href="/vAmiga/docs/api/vamiga-VAmiga#vamiga">vamiga::VAmiga</a>. It has two kinds of members:</p><ul><li><strong>Functions</strong> that act on the emulator as a whole: querying the version, launching the emulator thread, controlling the execution state, resetting, configuring, and synchronizing with the emulator thread.</li><li><strong>Sub-APIs</strong>, one per hardware component or subsystem. They are public data members, so a call reads like <code>amiga.cpu.getInfo()</code> or <code>amiga.df0.insertBlankDisk(...)</code>. Sub-APIs may contain further sub-APIs, for example <code>amiga.cpu.breakpoints</code> or <code>amiga.controlPort1.joystick</code>.</li></ul><p>All API classes are derived from <a href="/vAmiga/docs/api/vamiga-API#api">vamiga::API</a>, which provides <a href="/vAmiga/docs/api/vamiga-API#suspend">suspend()</a> and <a href="/vAmiga/docs/api/vamiga-API#resume">resume()</a>.</p><h2 id="sub-apis" tabindex="-1">Sub-APIs <a class="header-anchor" href="#sub-apis" aria-label="Permalink to &quot;Sub-APIs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Member</th><th>Class</th><th>Purpose</th></tr></thead><tbody><tr><td><code>amiga</code></td><td><a href="/vAmiga/docs/api/vamiga-AmigaAPI#amigaapi">vamiga::AmigaAPI</a></td><td>The machine as a whole: snapshots, ROMs, media files, auto-inspection.</td></tr><tr><td><code>agnus</code></td><td><a href="/vAmiga/docs/api/vamiga-AgnusAPI#agnusapi">vamiga::AgnusAPI</a></td><td>The Agnus chip. Its members <code>copper</code> (<a href="/vAmiga/docs/api/vamiga-CopperAPI#copperapi">vamiga::CopperAPI</a>), <code>blitter</code> (<a href="/vAmiga/docs/api/vamiga-BlitterAPI#blitterapi">vamiga::BlitterAPI</a>), <code>xray</code> (<a href="/vAmiga/docs/api/vamiga-XRayAPI#xrayapi">vamiga::XRayAPI</a>), <code>logicAnalyzer</code> (<a href="/vAmiga/docs/api/vamiga-LogicAnalyzerAPI#logicanalyzerapi">vamiga::LogicAnalyzerAPI</a>) and <code>beamtraps</code> (<a href="/vAmiga/docs/api/vamiga-GuardsAPI#guardsapi">vamiga::GuardsAPI</a>) give access to the subcomponents.</td></tr><tr><td><code>ciaA</code>, <code>ciaB</code></td><td><a href="/vAmiga/docs/api/vamiga-CIAAPI#ciaapi">vamiga::CIAAPI</a></td><td>The two CIA chips.</td></tr><tr><td><code>cpu</code></td><td><a href="/vAmiga/docs/api/vamiga-CPUAPI#cpuapi">vamiga::CPUAPI</a></td><td>CPU state. Its members <code>debugger</code> (<a href="/vAmiga/docs/api/vamiga-CPUDebuggerAPI#cpudebuggerapi">vamiga::CPUDebuggerAPI</a>) disassembles code, <code>breakpoints</code>, <code>watchpoints</code> and <code>catchpoints</code> (<a href="/vAmiga/docs/api/vamiga-GuardsAPI#guardsapi">vamiga::GuardsAPI</a>) manage guards.</td></tr><tr><td><code>denise</code></td><td><a href="/vAmiga/docs/api/vamiga-DeniseAPI#deniseapi">vamiga::DeniseAPI</a></td><td>The Denise chip.</td></tr><tr><td><code>mem</code></td><td><a href="/vAmiga/docs/api/vamiga-MemoryAPI#memoryapi">vamiga::MemoryAPI</a></td><td>Memory configuration and state. Its member <code>debugger</code> (<a href="/vAmiga/docs/api/vamiga-MemoryDebuggerAPI#memorydebuggerapi">vamiga::MemoryDebuggerAPI</a>) dumps memory.</td></tr><tr><td><code>paula</code></td><td><a href="/vAmiga/docs/api/vamiga-PaulaAPI#paulaapi">vamiga::PaulaAPI</a></td><td>The Paula chip with its <code>diskController</code> (<a href="/vAmiga/docs/api/vamiga-DiskControllerAPI#diskcontrollerapi">vamiga::DiskControllerAPI</a>) and <code>uart</code> (<a href="/vAmiga/docs/api/vamiga-UARTAPI#uartapi">vamiga::UARTAPI</a>).</td></tr><tr><td><code>rtc</code></td><td><a href="/vAmiga/docs/api/vamiga-RTCAPI#rtcapi">vamiga::RTCAPI</a></td><td>The real-time clock.</td></tr><tr><td><code>audioPort</code>, <code>videoPort</code></td><td><a href="/vAmiga/docs/api/vamiga-AudioPortAPI#audioportapi">vamiga::AudioPortAPI</a>, <a href="/vAmiga/docs/api/vamiga-VideoPortAPI#videoportapi">vamiga::VideoPortAPI</a></td><td>Audio and video output.</td></tr><tr><td><code>controlPort1</code>, <code>controlPort2</code></td><td><a href="/vAmiga/docs/api/vamiga-ControlPortAPI#controlportapi">vamiga::ControlPortAPI</a></td><td>The control ports. Their members <code>joystick</code> (<a href="/vAmiga/docs/api/vamiga-JoystickAPI#joystickapi">vamiga::JoystickAPI</a>) and <code>mouse</code> (<a href="/vAmiga/docs/api/vamiga-MouseAPI#mouseapi">vamiga::MouseAPI</a>) control the connected device.</td></tr><tr><td><code>serialPort</code></td><td><a href="/vAmiga/docs/api/vamiga-SerialPortAPI#serialportapi">vamiga::SerialPortAPI</a></td><td>The serial port.</td></tr><tr><td><code>df0</code> ... <code>df3</code></td><td><a href="/vAmiga/docs/api/vamiga-FloppyDriveAPI#floppydriveapi">vamiga::FloppyDriveAPI</a></td><td>The floppy drives and their disks.</td></tr><tr><td><code>hd0</code> ... <code>hd3</code></td><td><a href="/vAmiga/docs/api/vamiga-HardDriveAPI#harddriveapi">vamiga::HardDriveAPI</a></td><td>The hard drives. Their member <code>controller</code> (<a href="/vAmiga/docs/api/vamiga-HdControllerAPI#hdcontrollerapi">vamiga::HdControllerAPI</a>) is the drive controller.</td></tr><tr><td><code>keyboard</code></td><td><a href="/vAmiga/docs/api/vamiga-KeyboardAPI#keyboardapi">vamiga::KeyboardAPI</a></td><td>Key presses.</td></tr><tr><td><code>msgQueue</code></td><td><a href="/vAmiga/docs/api/vamiga-MsgQueueAPI#msgqueueapi">vamiga::MsgQueueAPI</a></td><td>The message queue.</td></tr><tr><td><code>remoteManager</code></td><td><a href="/vAmiga/docs/api/vamiga-RemoteManagerAPI#remotemanagerapi">vamiga::RemoteManagerAPI</a></td><td>Remote servers (RetroShell, RPC, DAP, ...).</td></tr><tr><td><code>retroShell</code></td><td><a href="/vAmiga/docs/api/vamiga-RetroShellAPI#retroshellapi">vamiga::RetroShellAPI</a></td><td>The command console.</td></tr><tr><td><code>defaults</code> (static)</td><td><a href="/vAmiga/docs/api/vamiga-DefaultsAPI#defaultsapi">vamiga::DefaultsAPI</a></td><td>Persistent user defaults. Available without an emulator instance.</td></tr></tbody></table><h2 id="conventions" tabindex="-1">Conventions <a class="header-anchor" href="#conventions" aria-label="Permalink to &quot;Conventions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pattern</th><th>Meaning</th></tr></thead><tbody><tr><td><code>getConfig()</code>, <code>get(Opt)</code> / <code>set(Opt, ...)</code></td><td>Read and change the configuration. Options are identified by the enumeration <a href="/vAmiga/docs/api/enum-Opt">vamiga::Opt</a>.</td></tr><tr><td><code>getInfo()</code>, <code>getCachedInfo()</code>, <code>getMetrics()</code>, ...</td><td>Read the state of a component.</td></tr><tr><td><code>foo()</code> / <code>fooAsync()</code></td><td>Blocking and asynchronous flavor of a state-changing function.</td></tr></tbody></table><p>To be notified about events, read the messages from the message queue (<a href="/vAmiga/docs/api/vamiga-MsgQueueAPI#msgqueueapi">vamiga::MsgQueueAPI</a>). The messages are listed in the enumeration <a href="/vAmiga/docs/api/enum-Msg">vamiga::Msg</a>.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><p>API functions report failures by throwing exceptions derived from <a href="/vAmiga/docs/api/utl-Error#error">utl::Error</a>. Each function documents what it can throw with <code>@throw</code>.</p><table tabindex="0"><thead><tr><th>Exception</th><th>Meaning</th></tr></thead><tbody><tr><td><a href="/vAmiga/docs/api/vamiga-CoreError#coreerror">vamiga::CoreError</a></td><td>The request does not match the state of the emulator, e.g., an invalid option value or a missing ROM.</td></tr><tr><td><a href="/vAmiga/docs/api/utl-IOError#ioerror">utl::IOError</a></td><td>A file or folder could not be accessed.</td></tr><tr><td><a href="/vAmiga/docs/api/vamiga-MediaError#mediaerror">vamiga::MediaError</a></td><td>A ROM, snapshot, or disk image is invalid or not supported.</td></tr></tbody></table>',12)])])}const h=e(i,[["render",r]]);export{p as __pageData,h as default};
